import fs from'node:fs';import vm from'node:vm';import{LEGACY_PACT_ROD_ROWS}from'../../src/data/lib/pact-rod-profiles.js';
export function loadPactRodClient(context){if(!vm.isContext(context))vm.createContext(context);Object.assign(context,{LEGACY_PACT_ROD_ROWS});context.env??={};context.D??={};context.FROZEN??=false;for(const file of ['app/lib/native-actor-frame.js','app/32x-logic-pact-rod-spell.js']){const source=fs.readFileSync(new URL('../../src/'+file,import.meta.url),'utf8'),names=[...source.matchAll(/export function (\w+)/g)].map(m=>m[1]);vm.runInContext('(function(){'+source.replace(/^import [^\n]*\n/gm,'').replace(/^export /gm,'')+';Object.assign(globalThis,{'+names.join(',')+'})})()',context)}return context}
